top_level_options ! (# [doc = " The top-level command-line options struct."] # [doc = ""] # [doc = " For each option, one has to specify how it behaves with regard to the"] # [doc = " dependency tracking system of incremental compilation. This is done via the"] # [doc = " square-bracketed directive after the field type. The options are:"] # [doc = ""] # [doc = " - `[TRACKED]`"] # [doc = " A change in the given field will cause the compiler to completely clear the"] # [doc = " incremental compilation cache before proceeding."] # [doc = ""] # [doc = " - `[TRACKED_NO_CRATE_HASH]`"] # [doc = " Same as `[TRACKED]`, but will not affect the crate hash. This is useful for options that"] # [doc = " only affect the incremental cache."] # [doc = ""] # [doc = " - `[UNTRACKED]`"] # [doc = " Incremental compilation is not influenced by this option."] # [doc = ""] # [doc = " - `[SUBSTRUCT]`"] # [doc = " Second-level sub-structs containing more options."] # [doc = ""] # [doc = " If you add a new option to this struct or one of the sub-structs like"] # [doc = " `CodegenOptions`, think about how it influences incremental compilation. If in"] # [doc = " doubt, specify `[TRACKED]`, which is always \"correct\" but might lead to"] # [doc = " unnecessary re-compilation."] # [rustc_lint_opt_ty] pub struct Options { # [doc = " The crate config requested for the session, which may be combined"] # [doc = " with additional crate configurations during the compile process."] # [rustc_lint_opt_deny_field_access ("use `TyCtxt::crate_types` instead of this field")] crate_types : Vec < CrateType > [TRACKED] , optimize : OptLevel [TRACKED] , # [doc = " Include the `debug_assertions` flag in dependency tracking, since it"] # [doc = " can influence whether overflow checks are done or not."] debug_assertions : bool [TRACKED] , debuginfo : DebugInfo [TRACKED] , debuginfo_compression : DebugInfoCompression [TRACKED] , lint_opts : Vec < (String , lint :: Level) > [TRACKED_NO_CRATE_HASH] , lint_cap : Option < lint :: Level > [TRACKED_NO_CRATE_HASH] , describe_lints : bool [UNTRACKED] , output_types : OutputTypes [TRACKED] , search_paths : Vec < SearchPath > [UNTRACKED] , libs : Vec < NativeLib > [TRACKED] , sysroot : Sysroot [UNTRACKED] , target_triple : TargetTuple [TRACKED] , # [doc = " Effective logical environment used by `env!`/`option_env!` macros"] logical_env : FxIndexMap < String , String > [TRACKED] , test : bool [TRACKED] , error_format : ErrorOutputType [UNTRACKED] , diagnostic_width : Option < usize > [UNTRACKED] , # [doc = " If `Some`, enable incremental compilation, using the given"] # [doc = " directory to store intermediate results."] incremental : Option < PathBuf > [UNTRACKED] , assert_incr_state : Option < IncrementalStateAssertion > [UNTRACKED] , # [doc = " Set by the `Config::hash_untracked_state` callback for custom"] # [doc = " drivers to invalidate the incremental cache"] # [rustc_lint_opt_deny_field_access ("should only be used via `Config::hash_untracked_state`")] untracked_state_hash : Hash64 [TRACKED_NO_CRATE_HASH] , unstable_opts : UnstableOptions [SUBSTRUCT UnstableOptionsTargetModifiers UnstableOptions] , prints : Vec < PrintRequest > [UNTRACKED] , cg : CodegenOptions [SUBSTRUCT CodegenOptionsTargetModifiers CodegenOptions] , externs : Externs [UNTRACKED] , crate_name : Option < String > [TRACKED] , # [doc = " Indicates how the compiler should treat unstable features."] unstable_features : UnstableFeatures [TRACKED] , # [doc = " Indicates whether this run of the compiler is actually rustdoc. This"] # [doc = " is currently just a hack and will be removed eventually, so please"] # [doc = " try to not rely on this too much."] actually_rustdoc : bool [TRACKED] , # [doc = " Whether name resolver should resolve documentation links."] resolve_doc_links : ResolveDocLinks [TRACKED] , # [doc = " Control path trimming."] trimmed_def_paths : bool [TRACKED] , # [doc = " Specifications of codegen units / ThinLTO which are forced as a"] # [doc = " result of parsing command line options. These are not necessarily"] # [doc = " what rustc was invoked with, but massaged a bit to agree with"] # [doc = " commands like `--emit llvm-ir` which they're often incompatible with"] # [doc = " if we otherwise use the defaults of rustc."] # [rustc_lint_opt_deny_field_access ("use `Session::codegen_units` instead of this field")] cli_forced_codegen_units : Option < usize > [UNTRACKED] , # [rustc_lint_opt_deny_field_access ("use `Session::lto` instead of this field")] cli_forced_local_thinlto_off : bool [UNTRACKED] , # [doc = " Remap source path prefixes in all output (messages, object files, debug, etc.)."] remap_path_prefix : Vec < (PathBuf , PathBuf) > [TRACKED_NO_CRATE_HASH] , # [doc = " Base directory containing the `library/` directory for the Rust standard library."] # [doc = " Right now it's always `$sysroot/lib/rustlib/src/rust`"] # [doc = " (i.e. the `rustup` `rust-src` component)."] # [doc = ""] # [doc = " This directory is what the virtual `/rustc/$hash` is translated back to,"] # [doc = " if Rust was built with path remapping to `/rustc/$hash` enabled"] # [doc = " (the `rust.remap-debuginfo` option in `bootstrap.toml`)."] real_rust_source_base_dir : Option < PathBuf > [TRACKED_NO_CRATE_HASH] , # [doc = " Base directory containing the `compiler/` directory for the rustc sources."] # [doc = " Right now it's always `$sysroot/lib/rustlib/rustc-src/rust`"] # [doc = " (i.e. the `rustup` `rustc-dev` component)."] # [doc = ""] # [doc = " This directory is what the virtual `/rustc-dev/$hash` is translated back to,"] # [doc = " if Rust was built with path remapping to `/rustc/$hash` enabled"] # [doc = " (the `rust.remap-debuginfo` option in `bootstrap.toml`)."] real_rustc_dev_source_base_dir : Option < PathBuf > [TRACKED_NO_CRATE_HASH] , edition : Edition [TRACKED] , # [doc = " `true` if we're emitting JSON blobs about each artifact produced"] # [doc = " by the compiler."] json_artifact_notifications : bool [TRACKED] , # [doc = " `true` if we're emitting JSON timings with the start and end of"] # [doc = " high-level compilation sections"] json_timings : bool [UNTRACKED] , # [doc = " `true` if we're emitting a JSON blob containing the unused externs"] json_unused_externs : JsonUnusedExterns [UNTRACKED] , # [doc = " `true` if we're emitting a JSON job containing a future-incompat report for lints"] json_future_incompat : bool [TRACKED] , pretty : Option < PpMode > [UNTRACKED] , # [doc = " The (potentially remapped) working directory"] working_dir : RealFileName [TRACKED] , color : ColorConfig [UNTRACKED] , verbose : bool [TRACKED_NO_CRATE_HASH] , }) ;